{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C40"],
      "claim": "Meperidine absolute oral bioavailability was 0.57 ± 0.12 in normal male control subjects after oral administration versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Ofloxacin absolute oral bioavailability was >95% in healthy volunteers after a 200 mg oral dose versus IV, well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Pentazocine absolute oral bioavailability was 18% in healthy subjects given an oral solution, below the 20% threshold.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Most transferred absolute oral bioavailability measurements in healthy or normal subjects are well above 20%, including meperidine (~0.57), ofloxacin (>95%), fenspiride (90%), nalmefene (~40-50%), diltiazem (~38%), and tacrolimus (~20-25%). Only pentazocine has ordinary-condition absolute bioavailability clearly below 20%. Therefore high bioavailability is better supported.",
  "evidence_gaps": [
    "One evidence molecule (vicriviroc) has only qualitative 'excellent' bioavailability without a numeric F, so it is uninformative for the 20% threshold.",
    "Pentazocine records include an individual healthy-subject value above 20% (31.6%) alongside mean values near 18%; the contradictory direction is based on the mean/ordinary-condition absolute records, but this inconsistency adds some uncertainty.",
    "Tacrolimus oral bioavailability of approximately 20-25% sits near the threshold, supporting high but with less margin than other positive records."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

